# Writes the skee-ramp arcade's hedra command files and its carpet texture:
#   floor.txt + textures/carpet.png, wall.txt (the back wall), neon.txt (a star, a ring, a zigzag),
#   tray.txt (the ball tray at the lane's foot), ball.txt, flash.txt (the score flash disc).
# Run from models/env: /usr/bin/python3 make_env.py. Up Z, front -Y (hedra): world x = hedra x,
# world z = -hedra y. Colours are exact Bubblegum 16 steps (sRGB 0..1).
import math, random
from PIL import Image

def rgb(h):
    h = h.lstrip("#")
    return tuple(int(h[i:i + 2], 16) / 255 for i in (0, 2, 4))
def col(h, emit=False):
    r, g, b = rgb(h)
    s = f"--base-color {r:.4f} {g:.4f} {b:.4f}"
    return s + (f" --emission {r:.4f} {g:.4f} {b:.4f}" if emit else "")
def write(name, lines):
    open(name, "w").write("\n".join(lines) + "\n")
def box(name, x, z, y, sx, sz, sy, mat):
    return [f"add mesh cube --name {name} --size 1 --location {x:.3f} {-z:.3f} {y:.3f}",
            f"scale {sx:.3f} {sz:.3f} {sy:.3f}", "apply --scale", f"material assign {mat}"]

# ---------------------------------------------------------------- carpet: arcade zigzags and dots
TW, TH = 40, 36                                     # 10 x 9 m: 0.25 m a texel
base, zig, dot = rgb("#430067"), rgb("#94216a"), rgb("#16171a")
img = Image.new("RGB", (TW, TH), tuple(int(c * 255) for c in base))
px = img.load()
c255 = lambda c: tuple(int(v * 255) for v in c)
for row in range(0, TH, 6):                         # zigzag bands, two texels thick
    for x in range(TW):
        y = row + (x % 4 if x % 8 < 4 else 4 - x % 4) // 2
        px[x, y % TH] = c255(zig)
        px[x, (y + 1) % TH] = c255(zig)
random.seed(4)
for _ in range(40):                                 # dark confetti pairs between the bands
    x, y = random.randrange(TW), random.randrange(TH)
    if px[x, y] == c255(base) and px[(x + 1) % TW, y] == c255(base):
        px[x, y] = c255(dot)
        px[(x + 1) % TW, y] = c255(dot)
img.save("textures/carpet.png")
write("floor.txt", [
    "# The arcade floor: a 10 x 9 m plane (world z -2.2..6.8) of carpet, zigzag bands and dark confetti",
    "# painted in a palette-exact 40 x 36 texture. Generated by make_env.py. Up Z.", "new",
    "add mesh grid --name Floor --size 1 --x-subdivisions 5 --y-subdivisions 5 --location 0 -2.3 0",
    "scale 10 9 1", "apply --scale", "material new Carpet --base-color 1 1 1", "material assign Carpet",
    "active Floor", "mode edit", "select all", "uv project-from-view top --scale-to-bounds", "mode object",
    "material texture Carpet base-color textures/carpet.png", "shade flat", "export floor.glb"])

write("wall.txt", [
    "# The back wall: 10 m wide, 4.5 m tall at world z -2.2, a dark skirting band along its foot. Up Z.", "new",
    f"material new Wall {col('#430067')} --no-slot", f"material new Skirt {col('#94216a')} --no-slot",
    *box("Wall", 0, -2.25, 2.4, 10, 0.1, 3.6, "Wall"),
    *box("Skirt", 0, -2.17, 0.3, 10, 0.08, 0.6, "Skirt"),
    "select all", "shade flat", "export wall.glb"])

# ---------------------------------------------------------------- neon signs (unlit), 6 cm off the wall
L = ["# Neon signs for the back wall: a five-point star, a ring, a zigzag bolt. Flat, 6 cm thick, facing",
     "# the camera (-Y). Each centred on its own origin, placed in the bake. Up Z.", "new",
     f"material new Star {col('#ffd100', True)} --no-slot", f"material new Ring {col('#ff2674', True)} --no-slot",
     f"material new Bolt {col('#10d275', True)} --no-slot"]
# the star: a 10-sided circle, every other vertex pulled in
L += ["add mesh circle --name Star --vertices 10 --radius 0.45 --cap-fill triangle-fan --location -2.6 0 0 --rotation 90 0 18",
      "apply --rotation", "active Star", "mode edit", "select vert where \"index % 2 == 1 && index < 10\"",
      "push-pull -0.24", "select all", "extrude 0 -0.06 0", "mode object", "material assign Star"]
L += ["add mesh torus --name Ring --major-radius 0.38 --minor-radius 0.07 --major-segments 14 --minor-segments 4 --location 2.6 0 0 --rotation 90 0 0",
      "apply --rotation", "material assign Ring"]
for i, (dx, dz, a) in enumerate([(0.0, 0.32, 30), (0.0, 0.0, -30), (0.0, -0.32, 30)]):
    L += [f"add mesh cube --name B{i} --size 1 --location {dx} 0 {dz}", "scale 0.5 0.06 0.12", "apply --scale",
          f"set rotation 0 {a} 0", "apply --rotation", "material assign Bolt"]
L += ["select B0 B1 B2", "active B0", "join", "rename B0 Bolt", "translate 0 0 0",
      "select all", "shade flat", "export neon.glb"]
write("neon.txt", L)

write("tray.txt", [
    "# The ball tray at the lane's foot: a mint trough 1.1 x 0.36 m, its floor 0.42 m up, a 6 cm rim. Up Z,",
    "# front -Y; placed against the cabinet's front (world z 1.6..1.96).", "new",
    f"material new Tray {col('#007899')} --no-slot", f"material new Rim {col('#ff2674')} --no-slot",
    *box("Floor", 0, 0.18, 0.39, 1.1, 0.36, 0.06, "Tray"),
    *box("Front", 0, 0.34, 0.45, 1.1, 0.06, 0.12, "Rim"),
    *box("SideL", 0.53, 0.18, 0.45, 0.06, 0.36, 0.12, "Rim"),
    *box("SideR", -0.53, 0.18, 0.45, 0.06, 0.36, 0.12, "Rim"),
    *box("Leg", 0, 0.18, 0.18, 0.9, 0.3, 0.36, "Tray"),
    "select all", "shade flat", "export tray.glb"])

write("ball.txt", [
    "# A skee ball: a faceted sphere r 0.1 (exaggerated from 0.075), mint. Origin at its centre. Up Z.", "new",
    "add mesh ico-sphere --name Ball --subdivisions 2 --radius 0.1 --location 0 0 0",
    f"material new Ball {col('#10d275')}", "material assign Ball", "shade flat", "export ball.glb"])

write("flash.txt", [
    "# The score flash: a flat yellow disc r 0.1, 2 cm thick, lying in the XY plane (the game tilts it onto",
    "# the target board and scales it to the ring that scored). Unlit in the bake. Up Z.", "new",
    "add mesh cylinder --name Flash --vertices 14 --radius 0.1 --depth 0.02 --location 0 0 0",
    f"material new Flash {col('#ffd100', True)}", "material assign Flash", "shade flat", "export flash.glb"])
print("wrote floor, wall, neon, tray, ball, flash")
